import attr


def test_pre_init_with_kw_only_default_field():
    """
    Regression test: a __attrs_pre_init__ hook that accepts a keyword-only
    field which also has a default value used to raise a SyntaxError while
    compiling the generated __init__ source. The class should instead be
    created normally and the hook should receive the field's default value.
    """
    seen = {}

    @attr.define
    class Foo:
        kw_and_default: int = attr.field(kw_only=True, default=3)

        def __attrs_pre_init__(self, *, kw_and_default):
            seen["value"] = kw_and_default

    Foo()

    assert seen["value"] == 3

