import attrs
from contextlib import contextmanager
from attr.exceptions import FrozenInstanceError


@attrs.frozen
class MyException(Exception):
    pass


@contextmanager
def do_nothing():
    yield


def test_frozen_exception_traceback_reassignment_in_context_manager():
    """
    Regression test: frozen exceptions must allow __traceback__ to be
    (re)assigned, since that's part of normal exception machinery (e.g.
    triggered by contextlib.contextmanager based context managers), not
    user code mutating frozen fields.
    """
    try:
        with do_nothing():
            raise MyException()
    except MyException as e:
        caught = e
    else:
        pytest.fail("MyException was not raised/caught")

    # This should not raise FrozenInstanceError.
    caught.

