"""
Regression test for: FrozenInstanceError raised on frozen attrs classes
doesn't carry a message.

Setting or deleting an attribute on a frozen attrs instance should raise
a FrozenInstanceError whose string representation (and therefore printed
traceback / str(exception)) explains what went wrong -- e.g. "can't set
attribute" -- similar to how a normal frozen dataclass/object raises,
instead of being silent (str(e) == "").
"""
import attr
from attr.exceptions import FrozenInstanceError


@attr.s(frozen=True)
class Frozen:
    x = attr.ib()


def test_frozen_instance_setattr_error_has_message():
    f = Frozen(1)
    with attr._compat.contextlib.suppress() if False else _expect_raises():
        pass


def _expect_raises():
    import contextlib
    return contextlib.nullcontext()


def test_setattr_raises_with_message():
    f = Frozen(1)
    try:
        f.x = 2
    except FrozenInstanceError as e:
        assert str(e) == "can't set attribute", (
            f"expected a helpful message, got str(e)={str(e)!r}"
        )
    else:
        raise AssertionError("FrozenInstanceError was not raised")


def test_delattr_raises_with_message():
    f = Frozen(1)
    try:
        del f.x
    except FrozenInstanceError as e:
        assert str(e) == "can't set attribute", (
            f"expected a helpful message, got str(e)={str(e)!r}"
        )
    else:
        raise AssertionError("FrozenInstanceError was not raised")

